CREATE DATABASE IF NOT EXISTS genz_os CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE genz_os;
CREATE TABLE IF NOT EXISTS schema_migrations (version INT UNSIGNED NOT NULL PRIMARY KEY, applied_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS stations (id VARCHAR(64) NOT NULL PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,type ENUM('PC','PS5','PS4','PSVR','MOZA') NOT NULL,pc_tier ENUM('NORMAL','PREMIUM') NULL,status ENUM('AVAILABLE','BOOKED','ACTIVE','MAINTENANCE','BLOCKED') NOT NULL DEFAULT 'AVAILABLE',hourly_rate BIGINT UNSIGNED NOT NULL DEFAULT 0,slot_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 60,created_at DATETIME(3) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (id VARCHAR(64) NOT NULL PRIMARY KEY,station_id VARCHAR(64) NOT NULL,customer_name VARCHAR(120) NOT NULL,member_id VARCHAR(64) NULL,status ENUM('ACTIVE','PAUSED','ENDED') NOT NULL,started_at DATETIME(3) NOT NULL,scheduled_end_at DATETIME(3) NULL,paused_at DATETIME(3) NULL,paused_total_seconds INT UNSIGNED NOT NULL DEFAULT 0,ended_at DATETIME(3) NULL,token_hash CHAR(64) NOT NULL UNIQUE,gaming_balance BIGINT UNSIGNED NOT NULL DEFAULT 0,food_balance BIGINT UNSIGNED NOT NULL DEFAULT 0,CONSTRAINT fk_sessions_station FOREIGN KEY (station_id) REFERENCES stations(id),INDEX idx_sessions_station_status(station_id,status),INDEX idx_sessions_status(status),INDEX idx_sessions_station_scheduled_end(station_id,scheduled_end_at,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS session_pause_periods (id VARCHAR(64) NOT NULL PRIMARY KEY,session_id VARCHAR(64) NOT NULL,started_at DATETIME(3) NOT NULL,ended_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL,CONSTRAINT fk_pause_period_session FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE,INDEX idx_pause_period_session(session_id,started_at,ended_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS menu_items (id VARCHAR(64) NOT NULL PRIMARY KEY,name VARCHAR(160) NOT NULL,category VARCHAR(100) NOT NULL,image_url VARCHAR(500) NULL,member_price BIGINT UNSIGNED NOT NULL,non_member_price BIGINT UNSIGNED NOT NULL,stock_qty INT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,INDEX idx_menu_active(active,category)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(64) NOT NULL PRIMARY KEY,session_id VARCHAR(64) NOT NULL,station_id VARCHAR(64) NOT NULL,status ENUM('NEW','ACCEPTED','PREPARING','READY','DELIVERED','CANCELLED') NOT NULL,payment_mode ENUM('PAY_NOW','COUNTER') NOT NULL,payment_status ENUM('UNPAID','PENDING','PAID','FAILED','REFUNDED') NOT NULL DEFAULT 'UNPAID',paid_at DATETIME(3) NULL,razorpay_order_id VARCHAR(80) NULL,razorpay_payment_id VARCHAR(80) NULL,razorpay_signature VARCHAR(128) NULL,created_at DATETIME(3) NOT NULL,total BIGINT UNSIGNED NOT NULL DEFAULT 0,CONSTRAINT fk_orders_session FOREIGN KEY(session_id) REFERENCES sessions(id),CONSTRAINT fk_orders_station FOREIGN KEY(station_id) REFERENCES stations(id),UNIQUE KEY uq_orders_razorpay_order(razorpay_order_id),UNIQUE KEY uq_orders_razorpay_payment(razorpay_payment_id),INDEX idx_orders_session(session_id),INDEX idx_orders_status(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS members (id VARCHAR(64) NOT NULL PRIMARY KEY,name VARCHAR(120) NOT NULL,mobile VARCHAR(20) NOT NULL UNIQUE,tier ENUM('REGULAR','GOLD','VIP') NOT NULL DEFAULT 'REGULAR',expires_at DATE NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,INDEX idx_members_mobile_active(mobile,active),INDEX idx_members_expiry(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customers (id VARCHAR(64) NOT NULL PRIMARY KEY,mobile VARCHAR(20) NOT NULL UNIQUE,name VARCHAR(120) NULL,member_id VARCHAR(64) NULL,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,INDEX idx_customers_member(member_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_otp_challenges (id VARCHAR(64) NOT NULL PRIMARY KEY,mobile VARCHAR(20) NOT NULL,otp_hash CHAR(64) NOT NULL,expires_at DATETIME(3) NOT NULL,attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,consumed_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL,INDEX idx_otp_mobile_created(mobile,created_at),INDEX idx_otp_expiry(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_sessions (id VARCHAR(64) NOT NULL PRIMARY KEY,customer_id VARCHAR(64) NOT NULL,session_token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME(3) NOT NULL,created_at DATETIME(3) NOT NULL,last_seen_at DATETIME(3) NOT NULL,CONSTRAINT fk_customer_sessions_customer FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE,INDEX idx_customer_sessions_customer(customer_id),INDEX idx_customer_sessions_expiry(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS session_participants (id VARCHAR(64) NOT NULL PRIMARY KEY,session_id VARCHAR(64) NOT NULL,customer_id VARCHAR(64) NULL,member_id VARCHAR(64) NULL,display_name VARCHAR(120) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(3) NOT NULL,joined_at DATETIME(3) NULL,left_at DATETIME(3) NULL,billing_regular_rate BIGINT UNSIGNED NOT NULL DEFAULT 0,billing_member_rate BIGINT UNSIGNED NOT NULL DEFAULT 0,member_tier ENUM('REGULAR','GOLD','VIP') NULL,CONSTRAINT fk_participants_session FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE,CONSTRAINT fk_participants_customer FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,CONSTRAINT fk_participants_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE SET NULL,INDEX idx_participants_session(session_id,active,joined_at),INDEX idx_participants_customer(customer_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,order_id VARCHAR(64) NOT NULL,item_id VARCHAR(64) NOT NULL,name VARCHAR(160) NOT NULL,qty INT UNSIGNED NOT NULL,unit_price BIGINT UNSIGNED NOT NULL,participant_id VARCHAR(64) NULL,CONSTRAINT fk_order_items_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,CONSTRAINT fk_order_items_participant FOREIGN KEY(participant_id) REFERENCES session_participants(id) ON DELETE SET NULL,INDEX idx_order_items_order(order_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_transactions (id VARCHAR(64) NOT NULL PRIMARY KEY,order_id VARCHAR(64) NOT NULL,provider ENUM('RAZORPAY','COUNTER') NOT NULL,provider_order_id VARCHAR(80) NULL,provider_payment_id VARCHAR(80) NULL,status ENUM('CREATED','PENDING','CAPTURED','FAILED','REFUNDED') NOT NULL,amount BIGINT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'INR',created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,captured_at DATETIME(3) NULL,CONSTRAINT fk_payment_order FOREIGN KEY(order_id) REFERENCES orders(id),INDEX idx_payment_order(order_id,created_at),INDEX idx_payment_provider_order(provider_order_id),INDEX idx_payment_provider_payment(provider_payment_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bookings (id VARCHAR(64) NOT NULL PRIMARY KEY,station_id VARCHAR(64) NOT NULL,customer_name VARCHAR(120) NOT NULL,member_id VARCHAR(64) NULL,starts_at DATETIME(3) NOT NULL,ends_at DATETIME(3) NOT NULL,status ENUM('PENDING','CONFIRMED','PAID','CANCELLED','NO_SHOW') NOT NULL DEFAULT 'CONFIRMED',deposit BIGINT UNSIGNED NOT NULL DEFAULT 0,notes VARCHAR(500) NULL,created_at DATETIME(3) NOT NULL,CONSTRAINT fk_bookings_station FOREIGN KEY(station_id) REFERENCES stations(id),INDEX idx_bookings_station_time(station_id,starts_at,ends_at,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS gaming_rates (id VARCHAR(64) NOT NULL PRIMARY KEY,station_type ENUM('PC','PS5','PS4','PSVR','MOZA') NOT NULL,pc_tier ENUM('NORMAL','PREMIUM') NULL,label VARCHAR(100) NOT NULL,specs TEXT NULL,image_url VARCHAR(500) NULL,regular_price BIGINT UNSIGNED NOT NULL,member_price BIGINT UNSIGNED NOT NULL,unit_label VARCHAR(40) NOT NULL DEFAULT 'per hour',active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,INDEX idx_gaming_rates_active(active,station_type,pc_tier)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS member_price_rules (id VARCHAR(64) NOT NULL PRIMARY KEY,member_tier ENUM('REGULAR','GOLD','VIP') NOT NULL,category VARCHAR(100) NOT NULL,discount_percent DECIMAL(5,2) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE KEY uq_member_price_rule(member_tier,category)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS session_groups (id VARCHAR(64) NOT NULL PRIMARY KEY,name VARCHAR(100) NOT NULL,status ENUM('OPEN','CLOSED') NOT NULL DEFAULT 'OPEN',created_at DATETIME(3) NOT NULL,closed_at DATETIME(3) NULL,INDEX idx_session_groups_status(status,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS session_group_members (group_id VARCHAR(64) NOT NULL,session_id VARCHAR(64) NOT NULL PRIMARY KEY,created_at DATETIME(3) NOT NULL,CONSTRAINT fk_group_members_group FOREIGN KEY(group_id) REFERENCES session_groups(id) ON DELETE CASCADE,CONSTRAINT fk_group_members_session FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE,INDEX idx_group_members_group(group_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS staff_users (id VARCHAR(64) NOT NULL PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('OWNER','MANAGER','CASHIER','KITCHEN','FLOOR') NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,INDEX idx_staff_active_role(active,role)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS staff_sessions (id VARCHAR(64) NOT NULL PRIMARY KEY,staff_id VARCHAR(64) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME(3) NOT NULL,created_at DATETIME(3) NOT NULL,last_seen_at DATETIME(3) NOT NULL,CONSTRAINT fk_staff_sessions_staff FOREIGN KEY(staff_id) REFERENCES staff_users(id) ON DELETE CASCADE,INDEX idx_staff_sessions_staff(staff_id),INDEX idx_staff_sessions_expiry(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,staff_id VARCHAR(64) NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80) NULL,entity_id VARCHAR(64) NULL,details JSON NULL,created_at DATETIME(3) NOT NULL,CONSTRAINT fk_audit_staff FOREIGN KEY(staff_id) REFERENCES staff_users(id) ON DELETE SET NULL,INDEX idx_audit_created(created_at),INDEX idx_audit_staff(staff_id),INDEX idx_audit_entity(entity_type,entity_id)) ENGINE=InnoDB;
INSERT INTO member_price_rules(id,member_tier,category,discount_percent,active) VALUES('RULE-REGULAR-ALL','REGULAR','ALL',0,TRUE),('RULE-GOLD-ALL','GOLD','ALL',10,TRUE),('RULE-VIP-ALL','VIP','ALL',15,TRUE) ON DUPLICATE KEY UPDATE discount_percent=VALUES(discount_percent),active=VALUES(active);
